import type { PortfolioSnapshot, RiskAnalysis } from "@/types";
import { formatPct, formatUsd } from "@/lib/utils/format";

/**
 * Template responses used ONLY when NEAR AI Cloud is not configured (or a
 * demo visitor is not allowed live inference). They are generated from the
 * sample data with plain string templates — no model is involved — and the
 * UI labels them "Demo response — not generated by NEAR AI".
 */
export function demoAnswer(question: string, p: PortfolioSnapshot, r: RiskAnalysis): string {
  const q = question.toLowerCase();
  const top = p.allocation[0];
  const cat = (id: string) => r.categories.find((c) => c.id === id);
  const note = "\n\n> _Demo response generated from a template over sample data — not produced by NEAR AI. Configure `NEAR_AI_API_KEY` for confidential live analysis._";

  if (/risk|report/.test(q)) {
    return `## Risk overview (sample data)

**Facts**
- Overall risk score: **${r.overallScore === null ? "n/a" : Math.round(r.overallScore)} / 100** (${r.level}).
${r.categories.map((c) => `- ${c.label}: ${c.score === null ? "insufficient data" : Math.round(c.score)}`).join("\n")}

**Interpretation**
- The largest contributors are ${[...r.categories].filter((c) => c.score !== null).sort((a, b) => (b.score ?? 0) * b.weight - (a.score ?? 0) * a.weight).slice(0, 2).map((c) => c.label.toLowerCase()).join(" and ")}.
- A sample wallet attempted a failed \`claim\` call to an unknown token contract — a common phishing pattern. Avoid interacting with unsolicited tokens.

This is not financial advice.${note}`;
  }
  if (/concentrat|exposure|allocation/.test(q)) {
    return `## Concentration (sample data)

**Facts**
- ${top?.symbol} represents **${formatPct(top?.pct ?? 0, { digits: 1 })}** of priced value.
- Concentration score: ${Math.round(cat("concentration")?.score ?? 0)} / 100 — ${cat("concentration")?.explanation}

**Interpretation**
- A single-asset drawdown would dominate portfolio outcomes. Consider whether that matches your risk tolerance.

This is not financial advice.${note}`;
  }
  if (/perform|poor|worst|loss/.test(q)) {
    const worst = [...p.holdings].filter((h) => h.change24hPct !== null).sort((a, b) => (a.change24hPct ?? 0) - (b.change24hPct ?? 0))[0];
    return `## Performance (sample data)

**Facts**
- Weakest 24h performer: **${worst?.symbol}** at ${formatPct(worst?.change24hPct ?? null, { sign: true })}.
- Portfolio 24h change: ${formatPct(p.change24hPct, { sign: true })} (${formatUsd(p.change24hUsd)}).
- ${cat("performance")?.explanation}

**Interpretation**
- Short-term moves are noisy; review whether each position still matches your thesis.

This is not financial advice.${note}`;
  }
  if (/transact|trade|behavio|activity/.test(q)) {
    return `## Recent activity (sample data)

**Facts**
- 10 sample transactions over ~3 weeks: swaps via Ref Finance, a stake deposit, an Intents withdrawal, two large exchange transfers, and one **failed** call to an unknown \`claim\` contract.
- An access key was added 21 days ago.

**Interpretation**
- Activity looks like a mix of DeFi use and exchange on/off-ramping. Review the added access key if you do not recognise it.

This is not financial advice.${note}`;
  }
  return `## Portfolio snapshot (sample data)

**Facts**
- Total priced value: **${formatUsd(p.totalValueUsd)}** across ${p.wallets.length} sample wallets.
- 24h change: ${formatPct(p.change24hPct, { sign: true })}.
- Allocation: ${p.allocation.map((a) => `${a.symbol} ${formatPct(a.pct, { digits: 1 })}`).join(", ")}.
- ${p.unpricedAssets} unpriced asset(s) excluded from totals.

**Interpretation**
- The portfolio is NEAR-heavy with a meaningful stablecoin buffer. Ask me about risks, concentration, performance or recent transactions.

This is not financial advice.${note}`;
}
